using System;using System.IO;using UnityEngine;using UnityEditor;
public static partial class HedgeDetailUpdater {
static void ApplyLeafAtlas(){string jpg="Assets/Scenes/Oasis/3D/Texture/petrol atlas.jpg",png="Assets/Scenes/Oasis/3D/Texture/petrol atlas.png";Directory.CreateDirectory("FinalEnvironmentRoadBackup/HedgeTexture");string backup="FinalEnvironmentRoadBackup/HedgeTexture/petrol atlas-original.jpg";if(!File.Exists(backup))File.Copy(jpg,backup);var atlas=new Texture2D(2,2,TextureFormat.RGBA32,false);atlas.LoadImage(File.ReadAllBytes(backup));var tile=new Texture2D(2,2,TextureFormat.RGB24,false);tile.LoadImage(File.ReadAllBytes("FinalEnvironmentRoadReview/HedgeLeafTile.png"));var pixels=atlas.GetPixels32();var before=(Color32[])pixels.Clone();int w=atlas.width,h=atlas.height,changed=0;foreach(var rect in new[]{new Rect(.004f,.267f,.149f,.067f),new Rect(.194f,.267f,.155f,.067f)}){int x0=Mathf.RoundToInt(rect.x*w),x1=Mathf.RoundToInt(rect.xMax*w),y0=Mathf.RoundToInt(rect.y*h),y1=Mathf.RoundToInt(rect.yMax*h);float period=(y1-y0);for(int y=y0;y<y1;y++)for(int x=x0;x<x1;x++){float u=Mathf.Repeat((x-x0)/period,1),v=(y-y0)/period;pixels[y*w+x]=tile.GetPixelBilinear(u,v);changed++;}}atlas.SetPixels32(pixels);atlas.Apply();if(File.Exists(jpg)){string err=AssetDatabase.MoveAsset(jpg,png);if(!string.IsNullOrEmpty(err))throw new Exception(err);}File.WriteAllBytes(png,atlas.EncodeToPNG());AssetDatabase.ImportAsset(png,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);UnityEngine.Object.DestroyImmediate(atlas);UnityEngine.Object.DestroyImmediate(tile);File.WriteAllText("FinalEnvironmentRoadReview/HedgeLeafAtlas.txt","Leaf albedo integrated into existing atlas GUID abfb374d42ae4eb4a99aebe7f8f86d59, same 4096 size. Only two existing hedge UV islands replaced. All other decoded source pixels preserved exactly. PNG encoding avoids another JPEG quality loss. Same material and texture slot. Replaced texels="+changed);Repair();}
